// Instalaciones de Distribución - Estructura tipo T2 (por unidades + simulacro)
// A falta de preguntas oficiales reales de la plataforma, se usan preguntas
// elaboradas a partir de los PDFs U1-U7 del temario, marcadas como TEST OFICIAL.
// Cada unidad cuenta con un banco de 20 preguntas; el simulacro toma una selección de 40 preguntas.

const TEMA_DISTRIBUCION_U1_DATA = [
  { id: 600101, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Cuál es la definición de riesgo laboral según la LPRL?", opciones: ["Probabilidad de que un trabajador sufra un daño derivado del trabajo", "Daño ya ocurrido al trabajador", "Protección contra accidentes", "Cantidad de equipos de seguridad"], correctaTexto: "Probabilidad de que un trabajador sufra un daño derivado del trabajo", explicacion: "El riesgo laboral es la probabilidad de que un trabajador sufra un daño derivado del trabajo, pudiendo causar lesión, enfermedad o muerte." },
  { id: 600102, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Cuál es el riesgo más grave en trabajos con electricidad?", opciones: ["Electrocución por contacto con partes activas", "Estrés visual", "Cansancio físico", "Problemas ergonómicos"], correctaTexto: "Electrocución por contacto con partes activas", explicacion: "El contacto con partes activas es el riesgo principal en instalaciones eléctricas, pudiendo causar electrocución, quemaduras severas o incluso la muerte." },
  { id: 600103, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué significa la sigla EPI?", opciones: ["Equipo de Protección Individual", "Elemento de Protección Integrada", "Equipamiento Protector Industrial", "Equipo Personal Integral"], correctaTexto: "Equipo de Protección Individual", explicacion: "EPI son los Equipos de Protección Individual que usa cada trabajador para protegerse de riesgos: casco, guantes, arnés, gafas, etc." },
  { id: 600104, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Cuál es la jerarquía de medidas preventivas?", opciones: ["Eliminar, sustituir, controlar, protección colectiva, protección individual", "Protección individual primero", "Solo control administrativo", "No existe jerarquía"], correctaTexto: "Eliminar, sustituir, controlar, protección colectiva, protección individual", explicacion: "La LPRL establece una jerarquía: eliminar riesgos, sustituir por alternativas menos peligrosas, medidas de control, protecciones colectivas y finalmente protecciones individuales." },
  { id: 600105, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Cuál es la tensión considerada de Muy Baja Tensión (MBT) según RBT?", opciones: ["Hasta 50V en corriente alterna", "Hasta 100V", "Hasta 10V", "No existe MBT"], correctaTexto: "Hasta 50V en corriente alterna", explicacion: "Muy Baja Tensión (MBT) es la tensión nominal igual o inferior a 50V en corriente alterna o 120V en corriente continua, según el RBT." },
  { id: 600106, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué se debe hacer antes de manipular cualquier instalación eléctrica?", opciones: ["Aplicar las cinco reglas de oro: desconectar, prevenir reconexión, verificar ausencia de tensión, poner a tierra y en cortocircuito, y señalizar", "Trabajar directamente sin comprobaciones", "Solo avisar a un compañero", "Usar guantes de algodón"], correctaTexto: "Aplicar las cinco reglas de oro: desconectar, prevenir reconexión, verificar ausencia de tensión, poner a tierra y en cortocircuito, y señalizar", explicacion: "Las cinco reglas de oro garantizan la seguridad antes de trabajar sin tensión: desconectar, prevenir reconexión, verificar ausencia de tensión, poner a tierra en cortocircuito y delimitar la zona de trabajo." },
  { id: 600107, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué norma regula en España la prevención de riesgos laborales con carácter general?", opciones: ["Ley 31/1995 de Prevención de Riesgos Laborales", "El Código Civil", "El Reglamento Electrotécnico de Baja Tensión", "La Ley de Ordenación de la Edificación"], correctaTexto: "Ley 31/1995 de Prevención de Riesgos Laborales", explicacion: "La Ley 31/1995 de Prevención de Riesgos Laborales (LPRL) es la norma marco que regula la prevención de riesgos laborales en España." },
  { id: 600108, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué es un accidente de trabajo según la normativa laboral?", opciones: ["Toda lesión corporal sufrida con ocasión o por consecuencia del trabajo", "Cualquier lesión sufrida fuera del horario laboral", "Solo lesiones graves con hospitalización", "Un incidente sin lesión"], correctaTexto: "Toda lesión corporal sufrida con ocasión o por consecuencia del trabajo", explicacion: "Se considera accidente de trabajo toda lesión corporal que el trabajador sufra con ocasión o como consecuencia del trabajo que ejecuta por cuenta ajena." },
  { id: 600109, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué es una enfermedad profesional?", opciones: ["La contraída como consecuencia del trabajo ejecutado, causada por agentes determinados en la normativa", "Cualquier enfermedad que padezca el trabajador", "Una lesión traumática súbita", "Un accidente in itinere"], correctaTexto: "La contraída como consecuencia del trabajo ejecutado, causada por agentes determinados en la normativa", explicacion: "La enfermedad profesional es la contraída a consecuencia del trabajo ejecutado por cuenta ajena, provocada por la acción de elementos o sustancias reconocidas en el cuadro legal correspondiente." },
  { id: 600110, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué distancia mínima de seguridad se debe respetar frente a elementos en tensión en instalaciones de alta tensión al trabajar sin tensión?", opciones: ["La determinada según la tensión nominal de la instalación, siguiendo la normativa vigente", "No existe distancia mínima obligatoria", "Siempre 1 metro sin excepción", "No es necesario mantener distancia alguna"], correctaTexto: "La determinada según la tensión nominal de la instalación, siguiendo la normativa vigente", explicacion: "Las distancias de seguridad varían según la tensión nominal de la instalación y están reguladas por el Reglamento sobre condiciones técnicas y garantías de seguridad en instalaciones eléctricas." },
  { id: 600111, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué elemento de protección colectiva se utiliza para delimitar una zona de trabajo eléctrico?", opciones: ["Vallado, señalización y balizamiento de la zona de trabajo", "Solo un cartel de advertencia", "Ningún elemento es necesario", "Un simple cordón de plástico sin señalización"], correctaTexto: "Vallado, señalización y balizamiento de la zona de trabajo", explicacion: "El vallado, la señalización y el balizamiento son medidas de protección colectiva que delimitan la zona de trabajo y advierten del riesgo eléctrico existente." },
  { id: 600112, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué tipo de guantes se deben usar para trabajos eléctricos en tensión?", opciones: ["Guantes aislantes homologados según la tensión de trabajo", "Guantes de cuero normales", "Guantes de algodón", "No es necesario usar guantes"], correctaTexto: "Guantes aislantes homologados según la tensión de trabajo", explicacion: "Los guantes aislantes deben estar homologados y ser adecuados a la clase de tensión de la instalación en la que se va a trabajar." },
  { id: 600113, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué residuos generados en el mantenimiento de centros de transformación se consideran peligrosos?", opciones: ["El aceite dieléctrico usado y los materiales contaminados con PCB", "El papel y cartón de embalaje", "Los restos de comida", "El agua de limpieza sin contaminantes"], correctaTexto: "El aceite dieléctrico usado y los materiales contaminados con PCB", explicacion: "El aceite dieléctrico usado y materiales que puedan contener PCB (bifenilos policlorados) se consideran residuos peligrosos y deben gestionarse conforme a la normativa ambiental." },
  { id: 600114, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué gestor debe encargarse de la retirada de residuos peligrosos generados en una instalación eléctrica?", opciones: ["Un gestor de residuos autorizado", "Cualquier empresa de transporte", "El propio trabajador sin control alguno", "No es necesario gestionar estos residuos"], correctaTexto: "Un gestor de residuos autorizado", explicacion: "Los residuos peligrosos deben ser retirados y tratados exclusivamente por gestores de residuos autorizados conforme a la legislación ambiental vigente." },
  { id: 600115, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué es el 'Plan de Prevención de Riesgos Laborales' de una empresa?", opciones: ["El instrumento que integra la actividad preventiva en el conjunto de sus actividades", "Un simple listado de EPIs", "Un documento opcional", "Un manual exclusivo de primeros auxilios"], correctaTexto: "El instrumento que integra la actividad preventiva en el conjunto de sus actividades", explicacion: "El Plan de Prevención de Riesgos Laborales es la herramienta a través de la cual se integra la actividad preventiva de la empresa en su sistema general de gestión." },
  { id: 600116, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué son las 'zonas de trabajo, proximidad y peligro' en instalaciones eléctricas?", opciones: ["Zonas delimitadas según la distancia a elementos en tensión que determinan el nivel de riesgo y las medidas a adoptar", "Solo una clasificación teórica sin aplicación práctica", "Áreas exclusivas para almacenamiento", "Zonas donde no aplica ninguna normativa"], correctaTexto: "Zonas delimitadas según la distancia a elementos en tensión que determinan el nivel de riesgo y las medidas a adoptar", explicacion: "El RD 614/2001 define zonas de trabajo, proximidad y peligro en función de la distancia a las partes en tensión, estableciendo las medidas preventivas correspondientes a cada una." },
  { id: 600117, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué formación específica debe recibir un trabajador autorizado para realizar trabajos en instalaciones eléctricas?", opciones: ["Formación específica en riesgo eléctrico según el RD 614/2001", "No se requiere formación específica", "Solo formación general de la empresa", "Formación exclusivamente en primeros auxilios"], correctaTexto: "Formación específica en riesgo eléctrico según el RD 614/2001", explicacion: "El RD 614/2001 exige que los trabajadores autorizados reciban formación específica sobre riesgo eléctrico adecuada a las funciones que van a desempeñar." },
  { id: 600118, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué debe hacerse en caso de incendio en un centro de transformación con presencia de aceite dieléctrico?", opciones: ["Utilizar extintores adecuados (CO2 o polvo) y nunca agua directamente sobre equipos en tensión", "Utilizar agua directamente sobre el transformador", "Ignorar el fuego si es pequeño", "Verter arena sin ningún extintor específico"], correctaTexto: "Utilizar extintores adecuados (CO2 o polvo) y nunca agua directamente sobre equipos en tensión", explicacion: "En incendios eléctricos con presencia de aceite se deben usar extintores de CO2 o polvo, evitando el agua mientras exista riesgo de tensión eléctrica." },
  { id: 600119, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué obligación tiene el empresario respecto a la evaluación de riesgos de un puesto de trabajo eléctrico?", opciones: ["Realizar una evaluación inicial de riesgos y actualizarla periódicamente", "No tiene ninguna obligación al respecto", "Solo evaluar riesgos tras un accidente", "Delegar toda la responsabilidad en el trabajador"], correctaTexto: "Realizar una evaluación inicial de riesgos y actualizarla periódicamente", explicacion: "El empresario está obligado a realizar una evaluación inicial de los riesgos del puesto de trabajo y mantenerla actualizada conforme cambien las condiciones." },
  { id: 600120, tema: "U1: Prevención de riesgos laborales y protección ambiental (TEST OFICIAL)", texto: "¿Qué es la 'vigilancia de la salud' de los trabajadores en el marco de la PRL?", opciones: ["El conjunto de actuaciones para controlar el estado de salud de los trabajadores en relación con los riesgos de su puesto", "Un examen médico exclusivamente al ingresar en la empresa", "Una obligación exclusiva del trabajador", "Una medida opcional sin relación con el puesto de trabajo"], correctaTexto: "El conjunto de actuaciones para controlar el estado de salud de los trabajadores en relación con los riesgos de su puesto", explicacion: "La vigilancia de la salud es el conjunto de actuaciones periódicas dirigidas a controlar el estado de salud de los trabajadores en relación con los riesgos derivados de su puesto de trabajo." }
];

const TEMA_DISTRIBUCION_U2_DATA = [
  { id: 600201, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué es un Centro de Transformación?", opciones: ["Local o espacio que contiene un transformador de distribución", "Una subestación de generación", "Un almacén de materiales", "Un taller de reparación"], correctaTexto: "Local o espacio que contiene un transformador de distribución", explicacion: "Un Centro de Transformación es un local o espacio que alberga equipos de transformación de la tensión de distribución a la de utilización en edificios." },
  { id: 600202, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Cuál es la función principal del transformador?", opciones: ["Transformar tensión y corriente alternada de un nivel a otro", "Generar electricidad", "Almacenar energía", "Proteger contra sobrecorrientes"], correctaTexto: "Transformar tensión y corriente alternada de un nivel a otro", explicacion: "El transformador convierte voltaje y corriente de un nivel a otro manteniendo constante la potencia (sin pérdidas ideales)." },
  { id: 600203, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿A qué tensión trabaja el lado primario en centros urbanos españoles?", opciones: ["20 kV", "230 V", "400 V", "10 kV"], correctaTexto: "20 kV", explicacion: "El lado primario del transformador en centros de distribución urbanos trabaja a 20 kV, que es la tensión de distribución estándar en España." },
  { id: 600204, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Cuál es la tensión de salida (secundaria) estándar?", opciones: ["230/400 V", "20 V", "10 kV", "6 kV"], correctaTexto: "230/400 V", explicacion: "El lado secundario del transformador proporciona 230/400 V para uso en edificios e instalaciones de baja tensión." },
  { id: 600205, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué medida de protección es obligatoria en el primario del transformador?", opciones: ["Seccionador y fusibles para cada transformador", "Solo interruptor", "No se requiere protección", "Pararrayos únicamente"], correctaTexto: "Seccionador y fusibles para cada transformador", explicacion: "Cada transformador debe tener seccionador y fusibles en el primario para protección y aislamiento según el REBT." },
  { id: 600206, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué función cumple la celda de protección en un centro de transformación?", opciones: ["Aislar y proteger el transformador frente a sobrecorrientes y cortocircuitos", "Almacenar herramientas", "Generar energía reactiva", "Medir la temperatura ambiente"], correctaTexto: "Aislar y proteger el transformador frente a sobrecorrientes y cortocircuitos", explicacion: "La celda de protección incluye los elementos de corte y protección (fusibles, interruptor) que aíslan el transformador ante fallos eléctricos." },
  { id: 600207, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué tipo de centro de transformación se instala en un edificio, integrado en su interior?", opciones: ["Centro de transformación interior o en local", "Centro de transformación aéreo sobre poste", "Centro de transformación móvil", "Centro de transformación subterráneo en pozo"], correctaTexto: "Centro de transformación interior o en local", explicacion: "El centro de transformación interior o en local es aquel ubicado dentro de un edificio, en una sala específicamente habilitada para este uso." },
  { id: 600208, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué tipo de centro de transformación se instala sobre un apoyo o poste, típico en zonas rurales?", opciones: ["Centro de transformación aéreo o sobre poste", "Centro de transformación en edificio prefabricado de hormigón", "Centro de transformación blindado en celda", "Centro de transformación subterráneo"], correctaTexto: "Centro de transformación aéreo o sobre poste", explicacion: "El centro de transformación aéreo, instalado sobre un poste, es habitual en zonas rurales por su menor coste frente a otras soluciones." },
  { id: 600209, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué elemento del centro de transformación permite maniobrar y aislar el circuito de media tensión sin necesidad de cortar la corriente de carga?", opciones: ["El interruptor-seccionador", "El transformador de potencia", "El embarrado de baja tensión", "El pararrayos"], correctaTexto: "El interruptor-seccionador", explicacion: "El interruptor-seccionador combina las funciones de maniobra bajo carga y de seccionamiento visible, garantizando la seguridad en las operaciones de mantenimiento." },
  { id: 600210, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué es el embarrado de un centro de transformación?", opciones: ["El conjunto de barras conductoras que distribuyen la energía entre las distintas celdas", "El cableado exterior de la acometida", "El sistema de ventilación del centro", "El sistema de puesta a tierra exclusivamente"], correctaTexto: "El conjunto de barras conductoras que distribuyen la energía entre las distintas celdas", explicacion: "El embarrado es el conjunto de barras conductoras (normalmente de cobre) que conectan eléctricamente las diferentes celdas del centro de transformación." },
  { id: 600211, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué función cumple el pararrayos o descargador de sobretensiones en un centro de transformación?", opciones: ["Proteger la instalación frente a sobretensiones de origen atmosférico o de maniobra", "Medir la energía consumida", "Reducir la tensión de línea", "Almacenar energía en caso de corte"], correctaTexto: "Proteger la instalación frente a sobretensiones de origen atmosférico o de maniobra", explicacion: "El pararrayos o descargador de sobretensiones deriva a tierra las sobretensiones de origen atmosférico o de maniobra que puedan dañar el transformador." },
  { id: 600212, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué sistema de refrigeración es el más habitual en transformadores de distribución de tamaño medio?", opciones: ["Refrigeración natural en aceite (ONAN)", "Refrigeración forzada por agua", "Refrigeración por aire acondicionado exclusivamente", "Sin ningún sistema de refrigeración"], correctaTexto: "Refrigeración natural en aceite (ONAN)", explicacion: "La refrigeración ONAN (Oil Natural Air Natural) es la más habitual en transformadores de distribución de tamaño medio, empleando el propio aceite como medio refrigerante." },
  { id: 600213, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué elemento del transformador indica visualmente el nivel de aceite dieléctrico?", opciones: ["El indicador de nivel de aceite (visor o mirilla)", "El termómetro de contacto", "El relé Buchholz exclusivamente", "El vaso de expansión sin indicador"], correctaTexto: "El indicador de nivel de aceite (visor o mirilla)", explicacion: "El indicador de nivel, generalmente una mirilla visible en el depósito de expansión, permite comprobar visualmente que el nivel de aceite es correcto." },
  { id: 600214, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué es el relé Buchholz en un transformador?", opciones: ["Un dispositivo de protección que detecta gases o pérdida de aceite provocados por fallos internos", "Un elemento decorativo del transformador", "Un tipo de fusible de baja tensión", "Un sistema de ventilación forzada"], correctaTexto: "Un dispositivo de protección que detecta gases o pérdida de aceite provocados por fallos internos", explicacion: "El relé Buchholz detecta la acumulación de gases o la pérdida de aceite derivados de fallos internos incipientes en el transformador, activando alarma o disparo." },
  { id: 600215, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué grupo de conexión es habitual en transformadores de distribución trifásicos según la norma IEC?", opciones: ["Dyn11", "YNy0 exclusivamente", "Solo transformadores monofásicos", "No existe estandarización de grupos de conexión"], correctaTexto: "Dyn11", explicacion: "El grupo de conexión Dyn11 (primario en triángulo, secundario en estrella con neutro accesible, desfase de 330°) es muy habitual en transformadores de distribución trifásicos." },
  { id: 600216, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué requisito de ventilación debe cumplir un centro de transformación interior?", opciones: ["Disponer de rejillas de ventilación natural o forzada para disipar el calor generado", "No requiere ventilación alguna", "Solo ventilación forzada eléctrica obligatoria", "Ventilación exclusivamente manual mediante puertas abiertas"], correctaTexto: "Disponer de rejillas de ventilación natural o forzada para disipar el calor generado", explicacion: "Los centros de transformación interiores deben contar con un sistema de ventilación (natural o forzada) que permita evacuar el calor generado por el transformador." },
  { id: 600217, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué es la puesta a tierra de servicio en un centro de transformación?", opciones: ["La conexión a tierra del neutro del secundario del transformador", "La conexión a tierra de las carcasas metálicas exclusivamente", "Un elemento decorativo sin función eléctrica", "La conexión entre dos fases del secundario"], correctaTexto: "La conexión a tierra del neutro del secundario del transformador", explicacion: "La puesta a tierra de servicio conecta a tierra el neutro del secundario del transformador, garantizando el correcto funcionamiento del sistema de distribución." },
  { id: 600218, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué es la puesta a tierra de protección en un centro de transformación?", opciones: ["La conexión a tierra de las masas metálicas para evitar tensiones peligrosas de contacto", "La conexión a tierra del neutro del secundario", "Un cable de repuesto sin uso eléctrico", "La conexión entre el primario y el secundario"], correctaTexto: "La conexión a tierra de las masas metálicas para evitar tensiones peligrosas de contacto", explicacion: "La puesta a tierra de protección conecta las masas metálicas (envolventes, carcasas) para evitar que aparezcan tensiones peligrosas de contacto en caso de defecto." },
  { id: 600219, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué establece la normativa respecto a la separación entre la puesta a tierra de protección y la de servicio en un centro de transformación?", opciones: ["Deben mantenerse separadas para evitar la transferencia de tensiones peligrosas, salvo que se demuestre que no existe riesgo", "Deben unirse siempre obligatoriamente sin excepción", "No existe ninguna recomendación al respecto", "Es indiferente su disposición"], correctaTexto: "Deben mantenerse separadas para evitar la transferencia de tensiones peligrosas, salvo que se demuestre que no existe riesgo", explicacion: "La normativa exige el estudio de la separación entre tierras de protección y de servicio para evitar transferencia de tensiones peligrosas a la instalación de baja tensión, salvo justificación técnica de que no existe riesgo." },
  { id: 600220, tema: "U2: Configuración de los centros de transformación (TEST OFICIAL)", texto: "¿Qué tipo de celda de un centro de transformación permite realizar mediciones de energía en media tensión?", opciones: ["La celda de medida", "La celda de protección de línea", "La celda de remonte de cables", "La celda de acoplamiento"], correctaTexto: "La celda de medida", explicacion: "La celda de medida incorpora los transformadores de tensión e intensidad necesarios para la medición de la energía consumida en el lado de media tensión." }
];

const TEMA_DISTRIBUCION_U3_DATA = [
  { id: 600301, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué es el mantenimiento preventivo?", opciones: ["Mantenimiento realizado antes de que falle el equipo para evitar roturas", "Reparación después de la avería", "Limpieza diaria", "Cambio de accesorios"], correctaTexto: "Mantenimiento realizado antes de que falle el equipo para evitar roturas", explicacion: "El mantenimiento preventivo es el conjunto de tareas realizadas de forma programada para prevenir fallos y alargar la vida útil del equipo." },
  { id: 600302, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué parámetro se debe medir regularmente en el aceite del transformador?", opciones: ["Humedad y rigidez dieléctrica", "Solo color", "Densidad únicamente", "Viscosidad nada más"], correctaTexto: "Humedad y rigidez dieléctrica", explicacion: "Los parámetros críticos del aceite son la humedad (debe ser mínima) y la rigidez dieléctrica (capacidad de aislamiento), que disminuyen con el tiempo." },
  { id: 600303, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué es una prueba termográfica en transformadores?", opciones: ["Uso de cámara infrarroja para detectar puntos calientes que indican problemas", "Prueba de temperatura con termómetro", "Medida del sonido", "Prueba de vibración"], correctaTexto: "Uso de cámara infrarroja para detectar puntos calientes que indican problemas", explicacion: "La termografía infrarroja identifica contactos sueltos, pérdidas de aceite, circulación deficiente y otros problemas mediante la detección de anomalías térmicas." },
  { id: 600304, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Cómo se detecta una fuga de aceite en el transformador?", opciones: ["Manchas de aceite en el suelo, baja del nivel, olor característico", "Solo por cambio de color", "No se detecta", "Mediante sonido"], correctaTexto: "Manchas de aceite en el suelo, baja del nivel, olor característico", explicacion: "Las fugas se detectan por manchas debajo del transformador, descenso del nivel de aceite visible en la ventanilla, y característico olor de aceite." },
  { id: 600305, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Cuál es la causa más común de fallo en transformadores?", opciones: ["Envejecimiento del aceite y sobrecalentamiento por mala disipación", "Falta de pintura", "Ruido excesivo", "Color diferente"], correctaTexto: "Envejecimiento del aceite y sobrecalentamiento por mala disipación", explicacion: "El deterioro del aislamiento por envejecimiento del aceite y temperatura elevada es la causa principal de fallos en transformadores." },
  { id: 600306, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Con qué periodicidad se recomienda realizar las revisiones periódicas de un centro de transformación?", opciones: ["Con una periodicidad establecida en el plan de mantenimiento, normalmente anual", "Solo cuando falla", "Cada 10 años", "Nunca, no requiere mantenimiento"], correctaTexto: "Con una periodicidad establecida en el plan de mantenimiento, normalmente anual", explicacion: "Los centros de transformación deben someterse a revisiones periódicas programadas, normalmente con carácter anual, para prevenir averías." },
  { id: 600307, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué es el mantenimiento correctivo?", opciones: ["El que se realiza tras la aparición de una avería para restablecer el funcionamiento del equipo", "El realizado de forma programada antes de la avería", "El que se realiza únicamente por indicación del fabricante cada año", "Un mantenimiento que solo afecta a la limpieza"], correctaTexto: "El que se realiza tras la aparición de una avería para restablecer el funcionamiento del equipo", explicacion: "El mantenimiento correctivo se lleva a cabo después de que se ha producido un fallo, con el objetivo de reparar el equipo y restablecer su funcionamiento normal." },
  { id: 600308, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué es el mantenimiento predictivo aplicado a centros de transformación?", opciones: ["El que se basa en el seguimiento de parámetros (temperatura, vibración, análisis de aceite) para anticipar fallos", "El que se realiza sin ningún tipo de medición previa", "Un mantenimiento exclusivamente estético", "El que consiste en sustituir el equipo cada año sin comprobación"], correctaTexto: "El que se basa en el seguimiento de parámetros (temperatura, vibración, análisis de aceite) para anticipar fallos", explicacion: "El mantenimiento predictivo se apoya en la monitorización continua de parámetros técnicos para anticipar el fallo antes de que se produzca, optimizando las intervenciones." },
  { id: 600309, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué prueba de laboratorio permite conocer el estado de degradación del aceite dieléctrico mediante el análisis de gases disueltos?", opciones: ["El análisis de gases disueltos en aceite (DGA)", "La prueba de continuidad", "La prueba de aislamiento con megóhmetro exclusivamente", "El ensayo de cortocircuito"], correctaTexto: "El análisis de gases disueltos en aceite (DGA)", explicacion: "El análisis de gases disueltos (DGA, Dissolved Gas Analysis) permite detectar fallos incipientes en el transformador a través de la composición de los gases generados por la degradación del aceite." },
  { id: 600310, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué revisión debe realizarse periódicamente sobre las conexiones y el embarrado de un centro de transformación?", opciones: ["Comprobación del apriete de las conexiones y ausencia de puntos calientes", "Ninguna, las conexiones no requieren revisión", "Solo revisión visual una vez cada diez años", "Sustitución completa cada mes"], correctaTexto: "Comprobación del apriete de las conexiones y ausencia de puntos calientes", explicacion: "Es fundamental comprobar periódicamente el correcto apriete de las conexiones y detectar posibles puntos calientes que puedan indicar un mal contacto." },
  { id: 600311, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué medición se debe realizar sobre la resistencia de puesta a tierra de un centro de transformación en las revisiones periódicas?", opciones: ["Medir el valor de la resistencia de tierra con telurómetro y compararlo con el valor de proyecto", "No es necesario medir la resistencia de tierra nunca", "Medir solo la tensión de la línea", "Medir exclusivamente la temperatura ambiente"], correctaTexto: "Medir el valor de la resistencia de tierra con telurómetro y compararlo con el valor de proyecto", explicacion: "La resistencia de puesta a tierra debe medirse periódicamente con un telurómetro para verificar que se mantiene dentro de los valores de diseño del proyecto." },
  { id: 600312, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué verificación de seguridad debe realizarse sobre los elementos de maniobra (interruptores, seccionadores) en el mantenimiento del centro de transformación?", opciones: ["Comprobar su correcto funcionamiento mecánico y el enclavamiento entre celdas", "No requieren ninguna comprobación", "Solo se revisan si fallan de forma evidente", "Se sustituyen automáticamente cada seis meses"], correctaTexto: "Comprobar su correcto funcionamiento mecánico y el enclavamiento entre celdas", explicacion: "Los elementos de maniobra deben revisarse comprobando su correcto accionamiento mecánico y el correcto funcionamiento de los enclavamientos de seguridad entre celdas." },
  { id: 600313, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué se debe verificar en el mantenimiento respecto a la ventilación del centro de transformación?", opciones: ["Que las rejillas de ventilación estén libres de obstrucciones y en buen estado", "Que las rejillas permanezcan siempre cerradas", "Que no exista ningún sistema de ventilación instalado", "Que el sistema de ventilación se desconecte permanentemente"], correctaTexto: "Que las rejillas de ventilación estén libres de obstrucciones y en buen estado", explicacion: "Debe comprobarse que las rejillas de ventilación estén limpias, libres de obstrucciones y en buen estado para asegurar la correcta disipación de calor." },
  { id: 600314, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué documento debe llevarse actualizado en cada intervención de mantenimiento de un centro de transformación?", opciones: ["El libro de mantenimiento o registro de intervenciones", "No es necesario documentar ninguna intervención", "Solo un correo electrónico informal", "Un documento sin firma ni fecha"], correctaTexto: "El libro de mantenimiento o registro de intervenciones", explicacion: "Cada intervención de mantenimiento debe quedar registrada en el libro de mantenimiento, documentando fecha, trabajos realizados y resultados obtenidos." },
  { id: 600315, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué implica un 'punto caliente' detectado mediante termografía en las conexiones de un centro de transformación?", opciones: ["Una posible conexión defectuosa o floja que debe ser corregida", "Una condición normal que no requiere actuación", "Un error de la cámara termográfica sin relevancia", "Una indicación de exceso de ventilación"], correctaTexto: "Una posible conexión defectuosa o floja que debe ser corregida", explicacion: "Un punto caliente detectado por termografía suele indicar una conexión defectuosa, oxidada o con apriete insuficiente, que debe corregirse para evitar averías mayores." },
  { id: 600316, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué prueba eléctrica permite medir el aislamiento entre bobinados y masa de un transformador?", opciones: ["Prueba de resistencia de aislamiento con megóhmetro", "Prueba de continuidad con multímetro", "Prueba de tensión de red exclusivamente", "Prueba de nivel de aceite"], correctaTexto: "Prueba de resistencia de aislamiento con megóhmetro", explicacion: "El megóhmetro permite medir la resistencia de aislamiento entre los bobinados y masa del transformador, verificando el estado del aislamiento eléctrico." },
  { id: 600317, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué precaución de seguridad es imprescindible antes de realizar cualquier operación de mantenimiento en el interior de un centro de transformación?", opciones: ["Aplicar las cinco reglas de oro y verificar la ausencia de tensión con detector homologado", "Entrar directamente sin ninguna comprobación previa", "Solo avisar verbalmente sin desconectar nada", "Confiar en que la instalación está sin tensión sin verificarlo"], correctaTexto: "Aplicar las cinco reglas de oro y verificar la ausencia de tensión con detector homologado", explicacion: "Antes de cualquier intervención en el interior de un centro de transformación es imprescindible aplicar las cinco reglas de oro, incluyendo la verificación de ausencia de tensión con un detector homologado." },
  { id: 600318, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué elemento de protección personal es imprescindible al manipular fusibles o elementos de media tensión en un centro de transformación?", opciones: ["Guantes aislantes de la clase adecuada a la tensión y pértiga aislante si procede", "Guantes de tela ordinarios", "Ningún equipo especial es necesario", "Solo gafas de sol"], correctaTexto: "Guantes aislantes de la clase adecuada a la tensión y pértiga aislante si procede", explicacion: "La manipulación de elementos de media tensión requiere el uso de guantes aislantes homologados de la clase adecuada, así como pértigas aislantes cuando la operación lo requiera." },
  { id: 600319, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué se recomienda hacer con el aceite dieléctrico usado retirado durante el mantenimiento de un transformador?", opciones: ["Almacenarlo en recipientes homologados y entregarlo a un gestor de residuos autorizado", "Verterlo directamente al alcantarillado", "Reutilizarlo sin ningún tratamiento en otro transformador", "Quemarlo sin control en el exterior"], correctaTexto: "Almacenarlo en recipientes homologados y entregarlo a un gestor de residuos autorizado", explicacion: "El aceite dieléctrico usado debe almacenarse en recipientes homologados y entregarse a un gestor de residuos autorizado, dado su carácter de residuo peligroso." },
  { id: 600320, tema: "U3: Operaciones de mantenimiento de centros de transformación (TEST OFICIAL)", texto: "¿Qué finalidad tiene el mantenimiento legal obligatorio (inspecciones periódicas) de un centro de transformación de alta tensión?", opciones: ["Verificar el cumplimiento de la reglamentación de seguridad industrial vigente", "No tiene ninguna finalidad práctica", "Es solo un trámite administrativo sin relación con la seguridad", "Sustituir completamente el centro cada revisión"], correctaTexto: "Verificar el cumplimiento de la reglamentación de seguridad industrial vigente", explicacion: "Las inspecciones periódicas obligatorias tienen como finalidad verificar que la instalación cumple con la reglamentación de seguridad industrial y condiciones técnicas exigidas." }
];

const TEMA_DISTRIBUCION_U4_DATA = [
  { id: 600401, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Cuál es la tensión nominal de una red de distribución de baja tensión según la normativa española?", opciones: ["Hasta 1.000 voltios", "Hasta 500 voltios", "Hasta 250 voltios", "Hasta 1.500 voltios"], correctaTexto: "Hasta 1.000 voltios", explicacion: "Según la normativa española, la baja tensión se define como la tensión cuyo valor eficaz no excede los 1.000 voltios en corriente alterna." },
  { id: 600402, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Cuál es el sistema de distribución de baja tensión más común en España?", opciones: ["Sistema TT (Tierra-Tierra)", "Sistema IT (Aislado-Tierra)", "Sistema TN (Tierra-Neutro)", "Sistema TR (Tierra-Referencia)"], correctaTexto: "Sistema TN (Tierra-Neutro)", explicacion: "El sistema TN es el más utilizado en distribuciones de baja tensión urbanas. Se caracteriza por tener el neutro conectado a tierra en la fuente y el conductor de protección conectado al neutro." },
  { id: 600403, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué es un diferencial o interruptor por corriente residual (RCD)?", opciones: ["Un dispositivo que regula la frecuencia de la corriente", "Un dispositivo que detecta fugas de corriente a tierra y desconecta el circuito", "Un dispositivo que aumenta la capacidad de carga", "Un dispositivo que transforma corriente alterna en continua"], correctaTexto: "Un dispositivo que detecta fugas de corriente a tierra y desconecta el circuito", explicacion: "El diferencial es fundamental para la protección de personas, ya que detecta corrientes de fuga hacia tierra y desconecta el circuito en milisegundos." },
  { id: 600404, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Cuál es la sensibilidad estándar de un diferencial para protección de personas?", opciones: ["10 mA", "30 mA", "100 mA", "500 mA"], correctaTexto: "30 mA", explicacion: "La norma europea establece 30 mA como sensibilidad estándar para diferenciales que protejan a personas en circuitos ordinarios." },
  { id: 600405, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Cuál es la caída de tensión máxima permitida entre el origen de la instalación y el punto de utilización?", opciones: ["5%", "3%", "10%", "15%"], correctaTexto: "3%", explicacion: "Según la normativa, la caída de tensión máxima en la instalación de baja tensión no debe exceder el 3% desde el origen hasta el punto de utilización más lejano." },
  { id: 600406, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué tipo de red de distribución de baja tensión es la más habitual en zonas urbanas por su fiabilidad?", opciones: ["Red en anillo o malla", "Red radial únicamente", "Red sin conexión a tierra", "Red monofásica sin neutro"], correctaTexto: "Red en anillo o malla", explicacion: "Las redes en anillo o malla se emplean en zonas urbanas porque permiten mantener el suministro ante una avería, mejorando la fiabilidad frente a las redes radiales simples." },
  { id: 600407, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué es una red radial de distribución de baja tensión?", opciones: ["Una red en la que cada punto de consumo se alimenta desde un único origen sin posibilidad de alimentación alternativa", "Una red que forma siempre un anillo cerrado", "Una red exclusivamente subterránea", "Una red sin ningún tipo de protección"], correctaTexto: "Una red en la que cada punto de consumo se alimenta desde un único origen sin posibilidad de alimentación alternativa", explicacion: "En una red radial, la energía fluye en un único sentido desde el centro de transformación hasta el punto de consumo, sin caminos alternativos en caso de avería." },
  { id: 600408, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué tipo de conductor se utiliza habitualmente en redes de distribución aéreas de baja tensión?", opciones: ["Conductor trenzado aislado tipo RZ (cable trenzado)", "Cable coaxial", "Cable de fibra óptica", "Cable telefónico de pares"], correctaTexto: "Conductor trenzado aislado tipo RZ (cable trenzado)", explicacion: "Las redes aéreas de baja tensión emplean habitualmente conductores trenzados aislados tipo RZ, que agrupan fases y neutro en un mismo conjunto compacto." },
  { id: 600409, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué tipo de conductor se emplea habitualmente en redes de distribución subterráneas de baja tensión?", opciones: ["Cable con aislamiento de polietileno reticulado (XLPE) tipo RV-K o similar", "Cable desnudo sin ningún tipo de aislamiento", "Cable telefónico convencional", "Cable de fibra óptica exclusivamente"], correctaTexto: "Cable con aislamiento de polietileno reticulado (XLPE) tipo RV-K o similar", explicacion: "Las redes subterráneas de baja tensión emplean cables con aislamiento de polietileno reticulado (XLPE), como los del tipo RV-K, adecuados para su instalación enterrada." },
  { id: 600410, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué elemento de protección se instala en el origen de cada derivación de una red de distribución de baja tensión?", opciones: ["Fusibles o interruptores automáticos de protección contra sobrecorrientes", "Solo un seccionador sin protección de sobrecorriente", "Ningún elemento de protección", "Solo un contador de energía"], correctaTexto: "Fusibles o interruptores automáticos de protección contra sobrecorrientes", explicacion: "Cada derivación de la red de baja tensión debe protegerse en su origen mediante fusibles o interruptores automáticos que actúen ante sobrecorrientes." },
  { id: 600411, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué es la sección de un conductor y por qué es importante en el diseño de una red de baja tensión?", opciones: ["El área de la sección transversal del conductor, que determina su capacidad de conducción de corriente y la caída de tensión", "Un parámetro sin relevancia técnica", "Solo afecta al color del cable", "Determina exclusivamente el precio del cable sin efectos técnicos"], correctaTexto: "El área de la sección transversal del conductor, que determina su capacidad de conducción de corriente y la caída de tensión", explicacion: "La sección del conductor es fundamental en el diseño, ya que determina tanto la intensidad máxima admisible como la caída de tensión resultante en la línea." },
  { id: 600412, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué se entiende por 'red mallada' en distribución de baja tensión?", opciones: ["Una red con múltiples interconexiones entre líneas que permite varios caminos posibles para la energía", "Una red compuesta únicamente por una sola línea", "Una red exclusivamente aérea sin conexión a tierra", "Una red sin ningún punto de derivación"], correctaTexto: "Una red con múltiples interconexiones entre líneas que permite varios caminos posibles para la energía", explicacion: "Una red mallada dispone de múltiples interconexiones entre líneas, lo que mejora la continuidad del suministro al existir varios caminos alternativos para la energía." },
  { id: 600413, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué factor de potencia se considera adecuado en una instalación eléctrica de baja tensión según normativa?", opciones: ["Un factor de potencia igual o superior a 0,9", "Un factor de potencia de 0,5 o inferior", "El factor de potencia no tiene ninguna relevancia normativa", "Un factor de potencia negativo"], correctaTexto: "Un factor de potencia igual o superior a 0,9", explicacion: "La normativa exige mantener un factor de potencia igual o superior a 0,9 para evitar penalizaciones por energía reactiva y mejorar la eficiencia de la red." },
  { id: 600414, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué es un armario de distribución en una red de baja tensión?", opciones: ["Un elemento situado en la vía pública que agrupa las protecciones y derivaciones de la red hacia los usuarios", "Un elemento decorativo sin función eléctrica", "Un tipo de transformador de distribución", "Un contador de energía individual"], correctaTexto: "Un elemento situado en la vía pública que agrupa las protecciones y derivaciones de la red hacia los usuarios", explicacion: "El armario de distribución (CDU) agrupa las protecciones de las diferentes derivaciones de la red de baja tensión hacia los usuarios, facilitando el mantenimiento." },
  { id: 600415, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué ventaja presenta una red subterránea de baja tensión frente a una red aérea?", opciones: ["Mayor seguridad frente a inclemencias meteorológicas y menor impacto visual", "Menor coste de instalación en todos los casos", "Mayor facilidad de reparación en caso de avería", "Requiere menos mantenimiento en todos los casos"], correctaTexto: "Mayor seguridad frente a inclemencias meteorológicas y menor impacto visual", explicacion: "Las redes subterráneas ofrecen mayor seguridad frente a fenómenos meteorológicos adversos (viento, hielo) y un menor impacto visual, aunque su coste de instalación suele ser mayor." },
  { id: 600416, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué es el neutro en un sistema trifásico de distribución de baja tensión?", opciones: ["El conductor que conecta el punto neutro del transformador y sirve de referencia de tensión", "Una fase adicional del sistema trifásico", "Un conductor exclusivamente de protección sin función de retorno", "Un elemento decorativo sin función"], correctaTexto: "El conductor que conecta el punto neutro del transformador y sirve de referencia de tensión", explicacion: "El neutro es el conductor conectado al punto neutro del transformador que sirve de referencia de tensión y por el que puede circular la corriente de desequilibrio entre fases." },
  { id: 600417, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué documento técnico regula las condiciones técnicas de las líneas de distribución de baja tensión en España?", opciones: ["El Reglamento Electrotécnico de Baja Tensión (REBT) y sus ITC", "El Código Técnico de la Edificación exclusivamente", "La Ley de Costas", "El Código Civil"], correctaTexto: "El Reglamento Electrotécnico de Baja Tensión (REBT) y sus ITC", explicacion: "El REBT y sus Instrucciones Técnicas Complementarias (ITC) regulan las condiciones técnicas y de seguridad de las instalaciones eléctricas de baja tensión en España." },
  { id: 600418, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué se entiende por 'desequilibrio de fases' en una red trifásica de baja tensión?", opciones: ["Una distribución desigual de cargas entre las tres fases que provoca corriente por el neutro", "Un fenómeno que nunca ocurre en instalaciones trifásicas", "La igualdad perfecta de cargas en las tres fases", "Un fallo exclusivo del transformador"], correctaTexto: "Una distribución desigual de cargas entre las tres fases que provoca corriente por el neutro", explicacion: "El desequilibrio de fases se produce cuando las cargas conectadas a cada fase no son iguales, generando una corriente de retorno por el conductor neutro." },
  { id: 600419, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué elemento permite seccionar y aislar un tramo de la red de baja tensión para labores de mantenimiento sin afectar al resto de la red?", opciones: ["El seccionador o cuchilla de línea en el armario de distribución", "El contador de energía del usuario final", "El interruptor diferencial de la vivienda", "El transformador de intensidad"], correctaTexto: "El seccionador o cuchilla de línea en el armario de distribución", explicacion: "Los seccionadores o cuchillas instalados en los armarios de distribución permiten aislar tramos concretos de la red para realizar labores de mantenimiento sin afectar a otros usuarios." },
  { id: 600420, tema: "U4: Configuración de redes de distribución de baja tensión (TEST OFICIAL)", texto: "¿Qué criterio se utiliza para dimensionar la sección de los conductores de una red de distribución de baja tensión?", opciones: ["La intensidad máxima admisible y la caída de tensión máxima permitida", "Únicamente el color del aislamiento del cable", "El precio más económico disponible sin ningún otro criterio técnico", "La longitud del cable exclusivamente sin considerar la carga"], correctaTexto: "La intensidad máxima admisible y la caída de tensión máxima permitida", explicacion: "El dimensionado de los conductores debe considerar tanto la intensidad máxima admisible del cable como la caída de tensión máxima permitida por la normativa." }
];

const TEMA_DISTRIBUCION_U5_DATA = [
  { id: 600501, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Cuáles son las herramientas básicas necesarias para el montaje de instalaciones de baja tensión?", opciones: ["Martillo, destornillador y cinta de aislar", "Destornillador, alicates, pelacables, cinta de aislar y multímetro", "Taladro, sierra y nivel", "Sólo un destornillador y un martillo"], correctaTexto: "Destornillador, alicates, pelacables, cinta de aislar y multímetro", explicacion: "El equipo básico de montaje incluye herramientas manuales de precisión y un multímetro para verificar continuidad y tensiones." },
  { id: 600502, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué es el empalme de conductores y cuál es el método más seguro para realizarlo?", opciones: ["La unión de dos cables; el método más seguro es usar cinta de aislar", "La unión de dos cables; el método más seguro es usar conectores de compresión o soldadura", "La separación de dos cables", "El cruzamiento de dos cables"], correctaTexto: "La unión de dos cables; el método más seguro es usar conectores de compresión o soldadura", explicacion: "Los empalmes deben realizarse con conectores de compresión, regletas de conexión o soldadura, nunca solamente con cinta de aislar." },
  { id: 600503, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué resistencia de aislamiento mínima es aceptable en un circuito de baja tensión?", opciones: ["0,5 MΩ", "1 MΩ", "5 MΩ", "10 MΩ"], correctaTexto: "1 MΩ", explicacion: "Según normativa, la resistencia de aislamiento mínima debe ser de 1 MΩ (1 megaohmio) entre conductores activos y tierra." },
  { id: 600504, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Cuál es el valor máximo de resistencia de tierra permitido en una instalación residencial ordinaria?", opciones: ["10 ohmios", "20 ohmios", "40 ohmios", "100 ohmios"], correctaTexto: "40 ohmios", explicacion: "El valor máximo recomendado es de 40 ohmios para instalaciones ordinarias; para instalaciones con diferencial de 30mA se requiere Rt≤1.200/I." },
  { id: 600505, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Cómo se comprueba el correcto funcionamiento de un diferencial?", opciones: ["Observando el indicador visual", "Presionando el botón de prueba (botón T) para simular una fuga", "Usando un megóhmetro", "Midiendo la tensión con un multímetro"], correctaTexto: "Presionando el botón de prueba (botón T) para simular una fuga", explicacion: "Todo diferencial tiene un botón T de prueba que simula una corriente de fuga; si funciona correctamente, desconectará el circuito." },
  { id: 600506, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué herramienta se utiliza para verificar la continuidad de un circuito antes de su puesta en servicio?", opciones: ["El óhmetro o multímetro en función de continuidad", "El barómetro", "El anemómetro", "El fasímetro únicamente"], correctaTexto: "El óhmetro o multímetro en función de continuidad", explicacion: "El óhmetro, generalmente integrado en el multímetro, permite verificar la continuidad de los conductores antes de energizar la instalación." },
  { id: 600507, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué tipo de tubo protector se emplea habitualmente en canalizaciones empotradas de baja tensión?", opciones: ["Tubo corrugado de plástico flexible", "Tubo de cristal", "Tubo de cerámica", "Tubo de madera"], correctaTexto: "Tubo corrugado de plástico flexible", explicacion: "El tubo corrugado de plástico flexible es el más habitual en canalizaciones empotradas de baja tensión por su facilidad de instalación y coste reducido." },
  { id: 600508, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué código de colores establece la normativa española para los conductores de fase, neutro y protección?", opciones: ["Marrón/negro/gris para fases, azul para neutro y verde-amarillo para protección", "Todos los conductores del mismo color", "Rojo para todos los conductores", "Blanco para fases y negro para neutro"], correctaTexto: "Marrón/negro/gris para fases, azul para neutro y verde-amarillo para protección", explicacion: "La normativa establece el código de colores: marrón, negro o gris para las fases, azul para el neutro y bicolor verde-amarillo exclusivamente para el conductor de protección." },
  { id: 600509, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué prueba debe realizarse antes de poner en servicio una instalación de baja tensión recién montada?", opciones: ["Verificación de continuidad, aislamiento y correcto funcionamiento de las protecciones", "Ninguna prueba es necesaria antes de energizar", "Solo una inspección visual superficial", "Solo comprobar el color de los cables"], correctaTexto: "Verificación de continuidad, aislamiento y correcto funcionamiento de las protecciones", explicacion: "Antes de la puesta en servicio se deben verificar la continuidad de los circuitos, la resistencia de aislamiento y el correcto funcionamiento de las protecciones instaladas." },
  { id: 600510, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué es un boletín eléctrico (Certificado de Instalación Eléctrica, CIE) y quién debe emitirlo?", opciones: ["Un documento que certifica que la instalación cumple el REBT, emitido por un instalador autorizado", "Un documento sin validez legal", "Un documento que solo emite el propietario de la vivienda", "Un simple recibo de material"], correctaTexto: "Un documento que certifica que la instalación cumple el REBT, emitido por un instalador autorizado", explicacion: "El boletín eléctrico o CIE es el documento mediante el cual un instalador autorizado certifica que la instalación cumple con el REBT, siendo necesario para dar de alta el suministro." },
  { id: 600511, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué elemento de protección se debe instalar al inicio de cada circuito interior de una vivienda según el REBT?", opciones: ["Un pequeño interruptor automático (PIA) magnetotérmico", "Un fusible de vidrio antiguo exclusivamente", "Ningún elemento de protección individual", "Solo un interruptor manual sin protección"], correctaTexto: "Un pequeño interruptor automático (PIA) magnetotérmico", explicacion: "Cada circuito interior de una vivienda debe protegerse en su origen mediante un PIA (pequeño interruptor automático) magnetotérmico, según establece el REBT." },
  { id: 600512, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué operación de mantenimiento debe realizarse periódicamente sobre los interruptores diferenciales instalados en una vivienda?", opciones: ["Pulsar el botón de test para comprobar su correcto disparo", "No requiere ningún mantenimiento", "Sustituirlo cada mes sin comprobación previa", "Desconectarlo permanentemente"], correctaTexto: "Pulsar el botón de test para comprobar su correcto disparo", explicacion: "Se recomienda pulsar periódicamente el botón de test de los diferenciales para verificar que disparan correctamente ante una fuga simulada." },
  { id: 600513, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué herramienta se utiliza para medir la resistencia de puesta a tierra de una instalación de baja tensión?", opciones: ["El telurómetro", "El multímetro exclusivamente", "El fasímetro", "El vatímetro"], correctaTexto: "El telurómetro", explicacion: "El telurómetro es el instrumento específico utilizado para medir el valor de la resistencia de puesta a tierra de una instalación." },
  { id: 600514, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué método de conexión se recomienda para unir conductores en cajas de derivación de una instalación de baja tensión?", opciones: ["Uso de regletas de conexión o bornas específicas homologadas", "Retorcer los cables sin ningún elemento adicional", "Unir los cables con cinta adhesiva común", "Soldar sin aislar posteriormente la unión"], correctaTexto: "Uso de regletas de conexión o bornas específicas homologadas", explicacion: "En las cajas de derivación se recomienda el uso de regletas de conexión o bornas homologadas que garanticen una unión segura y duradera de los conductores." },
  { id: 600515, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué se debe comprobar al detectar un disparo repetido de un interruptor diferencial en una instalación de baja tensión?", opciones: ["Localizar el circuito y el elemento que provoca la fuga de corriente mediante desconexión progresiva", "Sustituir el diferencial por uno de mayor sensibilidad sin investigar la causa", "Puentear el diferencial para evitar el disparo", "Ignorar el problema si el disparo no es constante"], correctaTexto: "Localizar el circuito y el elemento que provoca la fuga de corriente mediante desconexión progresiva", explicacion: "Ante un disparo repetido del diferencial debe localizarse el circuito y el elemento causante de la fuga, desconectando progresivamente los circuitos hasta aislar el problema. Nunca se debe puentear el diferencial." },
  { id: 600516, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué medida de seguridad se debe adoptar al trabajar en una instalación de baja tensión que no se puede desconectar completamente?", opciones: ["Delimitar la zona, usar herramientas y EPI aislantes adecuados a la tensión", "Trabajar sin ningún tipo de protección adicional", "Ignorar las medidas de seguridad si el trabajo es rápido", "Usar herramientas metálicas sin aislar"], correctaTexto: "Delimitar la zona, usar herramientas y EPI aislantes adecuados a la tensión", explicacion: "Cuando no es posible desconectar completamente la instalación, deben adoptarse medidas específicas de trabajo en tensión: delimitación de zona y uso de herramientas y EPI aislantes homologados." },
  { id: 600517, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué comprobación se realiza mediante la 'prueba de rigidez dieléctrica' en un cable de baja tensión?", opciones: ["Verificar que el aislamiento soporta una tensión determinada sin producirse una descarga disruptiva", "Medir el diámetro exterior del cable", "Verificar el color del aislamiento", "Comprobar el peso del cable por metro"], correctaTexto: "Verificar que el aislamiento soporta una tensión determinada sin producirse una descarga disruptiva", explicacion: "La prueba de rigidez dieléctrica somete al aislamiento del cable a una tensión determinada superior a la nominal, verificando que no se produce una descarga disruptiva a través del material aislante." },
  { id: 600518, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué implica encontrar una intensidad de fuga elevada al medir con una pinza amperimétrica sobre el conductor de protección de una instalación?", opciones: ["Una posible avería de aislamiento en algún receptor o circuito conectado", "Un funcionamiento absolutamente normal sin ninguna anomalía", "Que la instalación está sobredimensionada", "Que el diferencial está mal calibrado siempre"], correctaTexto: "Una posible avería de aislamiento en algún receptor o circuito conectado", explicacion: "Una intensidad de fuga elevada detectada en el conductor de protección suele indicar un defecto de aislamiento en algún receptor o tramo del circuito que debe ser localizado y reparado." },
  { id: 600519, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué normativa regula las condiciones técnicas mínimas que debe cumplir una instalación eléctrica de baja tensión en España?", opciones: ["El Reglamento Electrotécnico de Baja Tensión (REBT)", "El Código Técnico de la Edificación exclusivamente", "La Ley de Ordenación de la Edificación exclusivamente", "El Código de Comercio"], correctaTexto: "El Reglamento Electrotécnico de Baja Tensión (REBT)", explicacion: "El REBT es la norma de referencia que establece las condiciones técnicas y garantías de seguridad que deben cumplir las instalaciones eléctricas de baja tensión en España." },
  { id: 600520, tema: "U5: Operaciones de montaje y mantenimiento de baja tensión (TEST OFICIAL)", texto: "¿Qué documentación debe entregarse al titular de una instalación tras finalizar su montaje y puesta en marcha?", opciones: ["El boletín eléctrico y, si procede, el certificado de inspección inicial", "No es necesario entregar ninguna documentación", "Solo la factura de materiales", "Un simple albarán de entrega sin datos técnicos"], correctaTexto: "El boletín eléctrico y, si procede, el certificado de inspección inicial", explicacion: "Al finalizar el montaje, el instalador debe entregar al titular el boletín eléctrico y, cuando la instalación lo requiera, el certificado de inspección inicial correspondiente." }
];

const TEMA_DISTRIBUCION_U6_DATA = [
  { id: 600601, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es una instalación de enlace en el contexto de distribución eléctrica?", opciones: ["Una conexión temporal entre dos transformadores", "La instalación que conecta la red pública de distribución con la instalación interior del usuario", "Un cable de comunicación entre edificios", "La conexión entre dos fases"], correctaTexto: "La instalación que conecta la red pública de distribución con la instalación interior del usuario", explicacion: "La instalación de enlace es el conjunto de elementos que conectan la red pública de distribución con la instalación interior, incluyendo línea de acometida, caja de protección y centralización de contadores." },
  { id: 600602, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es una caja de protección y maniobra (CPM) en una instalación de enlace?", opciones: ["Un armario que solo contiene el contador", "Un elemento que contiene fusibles de protección y permite desconectar la instalación", "Una caja para guardar herramientas", "Un regulador de voltaje"], correctaTexto: "Un elemento que contiene fusibles de protección y permite desconectar la instalación", explicacion: "La CPM alberga fusibles de protección contra cortocircuitos de la acometida y un dispositivo de desconexión que permite aislar la instalación." },
  { id: 600603, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es la línea de acometida en una instalación de enlace?", opciones: ["El cable que conecta el contador con el interruptor diferencial", "El tramo de red pública que alimenta la instalación", "El cable que une dos contadores", "La línea de conexión a tierra"], correctaTexto: "El tramo de red pública que alimenta la instalación", explicacion: "La acometida es la parte de la instalación que conecta la red pública de distribución con la propiedad del usuario, incluyendo los conductores desde el punto de derivación." },
  { id: 600604, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué incluye la centralización de contadores?", opciones: ["Solo los contadores de energía activa", "Contadores de energía activa, reactiva y dispositivos de maniobra para cada usuario", "Un único contador para todo el edificio", "Transformadores de potencia"], correctaTexto: "Contadores de energía activa, reactiva y dispositivos de maniobra para cada usuario", explicacion: "La centralización de contadores es un conjunto de elementos que permite medir el consumo de cada usuario y desconectar individualmente su instalación." },
  { id: 600605, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es un TI (transformador de intensidad) en una instalación de enlace?", opciones: ["Un transformador que aumenta la tensión", "Un transformador que reduce la corriente para que el contador pueda medirla con seguridad", "Un transformador que cambia la frecuencia", "Un transformador para comunicaciones"], correctaTexto: "Un transformador que reduce la corriente para que el contador pueda medirla con seguridad", explicacion: "El TI (Toroid de Intensidad) reduce la corriente de acometida a niveles seguros para el contador cuando la intensidad es muy elevada." },
  { id: 600606, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es la Línea General de Alimentación (LGA) en una instalación de enlace de un edificio?", opciones: ["El tramo que enlaza la CGP con la centralización de contadores", "El cable que conecta directamente cada vivienda con la red pública", "Un cable exclusivo para el ascensor", "El cable de conexión a tierra del edificio"], correctaTexto: "El tramo que enlaza la CGP con la centralización de contadores", explicacion: "La LGA es el conjunto de conductores que enlazan la Caja General de Protección (CGP) con la centralización de contadores en edificios de varias viviendas." },
  { id: 600607, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es la Caja General de Protección (CGP)?", opciones: ["El elemento que aloja los fusibles de seguridad y marca el inicio de la propiedad del usuario", "Un armario para almacenar contadores exclusivamente", "El elemento de conexión final en la vivienda", "Un dispositivo de medida de energía"], correctaTexto: "El elemento que aloja los fusibles de seguridad y marca el inicio de la propiedad del usuario", explicacion: "La CGP aloja los elementos de protección (fusibles) que marcan el límite entre la red de la compañía distribuidora y la propiedad del usuario." },
  { id: 600608, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué son las Derivaciones Individuales (DI) en una instalación de enlace?", opciones: ["Los conductores que parten de la centralización de contadores hasta cada Cuadro General de Mando y Protección de cada usuario", "El cable que une dos centros de transformación", "La línea de conexión a tierra general del edificio", "El cable de acometida exclusivamente"], correctaTexto: "Los conductores que parten de la centralización de contadores hasta cada Cuadro General de Mando y Protección de cada usuario", explicacion: "Las Derivaciones Individuales son los conductores que, partiendo de la línea general de alimentación o de la centralización de contadores, suministran energía a cada usuario individual." },
  { id: 600609, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es el Cuadro General de Mando y Protección (CGMP) en una vivienda?", opciones: ["El cuadro donde se ubican el interruptor general automático, el diferencial y los PIA de cada circuito", "Un simple armario de almacenamiento", "El contador individual de la vivienda", "El punto de conexión con la red pública"], correctaTexto: "El cuadro donde se ubican el interruptor general automático, el diferencial y los PIA de cada circuito", explicacion: "El CGMP es el cuadro eléctrico de cada vivienda donde se instalan el interruptor de control de potencia (o general automático), el interruptor diferencial y los PIA de cada circuito interior." },
  { id: 600610, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué tipos de esquemas de centralización de contadores existen según su ubicación?", opciones: ["Concentración en un único lugar, en más de un lugar, o individual en cada planta", "Solo un único esquema posible", "Únicamente contadores individuales en cada vivienda sin centralización", "Solo esquemas de contadores en el exterior del edificio"], correctaTexto: "Concentración en un único lugar, en más de un lugar, o individual en cada planta", explicacion: "El REBT (ITC-BT-16) contempla distintos esquemas: concentración de contadores en un único lugar, en más de un lugar, o en varias centralizaciones parciales según la configuración del edificio." },
  { id: 600611, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué elemento de la instalación de enlace permite desconectar de forma general toda la instalación interior de un usuario?", opciones: ["El Interruptor de Control de Potencia (ICP) o el interruptor general automático", "El contador de energía exclusivamente", "El fusible de la CGP", "La toma de tierra"], correctaTexto: "El Interruptor de Control de Potencia (ICP) o el interruptor general automático", explicacion: "El ICP (o interruptor general automático en instalaciones modernas) permite desconectar de forma general la instalación interior del usuario y limita la potencia contratada." },
  { id: 600612, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Dónde se ubica habitualmente la Caja General de Protección (CGP) en un edificio de viviendas?", opciones: ["En la fachada exterior o en un nicho accesible desde la vía pública", "Siempre en el interior de cada vivienda", "En la azotea del edificio exclusivamente", "En el sótano sin acceso desde el exterior"], correctaTexto: "En la fachada exterior o en un nicho accesible desde la vía pública", explicacion: "La CGP se instala habitualmente en la fachada exterior del edificio o en un nicho de fácil y libre acceso desde la vía pública, según establece el REBT." },
  { id: 600613, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué grado de protección IP mínimo debe cumplir la envolvente de una Caja General de Protección instalada en el exterior?", opciones: ["Un grado de protección IP adecuado para exteriores establecido en el REBT (ITC-BT-13)", "No requiere ningún grado de protección específico", "Solo protección frente a polvo sin protección al agua", "Un grado inferior al exigido en interiores"], correctaTexto: "Un grado de protección IP adecuado para exteriores establecido en el REBT (ITC-BT-13)", explicacion: "La ITC-BT-13 del REBT establece los grados de protección IP que deben cumplir las envolventes de las CGP instaladas a la intemperie, garantizando su estanqueidad." },
  { id: 600614, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué instrucción técnica complementaria del REBT regula específicamente las instalaciones de enlace?", opciones: ["ITC-BT-12 a ITC-BT-17", "ITC-BT-51 exclusivamente", "ITC-BT-40 exclusivamente", "ITC-BT-30 exclusivamente"], correctaTexto: "ITC-BT-12 a ITC-BT-17", explicacion: "Las instrucciones ITC-BT-12 a ITC-BT-17 del REBT regulan específicamente las distintas partes de las instalaciones de enlace: acometidas, CGP, LGA, contadores y derivaciones individuales." },
  { id: 600615, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué elemento adicional se instala en la centralización de contadores para telegestión y telemedida?", opciones: ["Un módulo de comunicaciones (concentrador) que transmite los datos de consumo a la distribuidora", "Un simple interruptor manual sin comunicación", "Ningún elemento adicional es necesario", "Un transformador de potencia adicional"], correctaTexto: "Un módulo de comunicaciones (concentrador) que transmite los datos de consumo a la distribuidora", explicacion: "Los contadores inteligentes actuales incorporan módulos de comunicación (PLC u otros) que permiten la telegestión y telemedida, transmitiendo los datos de consumo a la compañía distribuidora." },
  { id: 600616, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué establece la normativa sobre el conductor de protección en las derivaciones individuales?", opciones: ["Debe instalarse siempre un conductor de protección independiente hasta cada Cuadro General de Mando y Protección", "No es necesario instalar conductor de protección en derivaciones individuales", "Solo se instala en instalaciones industriales", "Se puede sustituir por conexión a la tubería de agua"], correctaTexto: "Debe instalarse siempre un conductor de protección independiente hasta cada Cuadro General de Mando y Protección", explicacion: "La ITC-BT-15 exige que cada derivación individual incluya un conductor de protección independiente que llegue hasta el cuadro general de mando y protección de cada usuario." },
  { id: 600617, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué canalización se recomienda para las derivaciones individuales en un edificio de varias plantas?", opciones: ["Canaladura o conducto de obra vertical (patinillo) con registros en cada planta", "Cableado visto sin ninguna protección", "Un único tubo compartido para todas las derivaciones sin separación", "Canalización exclusivamente subterránea fuera del edificio"], correctaTexto: "Canaladura o conducto de obra vertical (patinillo) con registros en cada planta", explicacion: "Las derivaciones individuales discurren habitualmente por una canaladura o patinillo vertical, con registros en cada planta para facilitar el mantenimiento y la inspección." },
  { id: 600618, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué elemento marca el límite de propiedad entre la instalación de la compañía distribuidora y la del usuario?", opciones: ["La Caja General de Protección (CGP)", "El contador de energía", "El Cuadro General de Mando y Protección", "El interruptor diferencial de la vivienda"], correctaTexto: "La Caja General de Protección (CGP)", explicacion: "La CGP marca habitualmente el límite entre la instalación de la compañía distribuidora (acometida) y la instalación propiedad del usuario." },
  { id: 600619, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué tipo de acometida existe según el trazado de la línea que alimenta la instalación de enlace?", opciones: ["Acometida aérea, subterránea o mixta", "Solo acometida aérea", "Solo acometida subterránea", "Solo acometida por fibra óptica"], correctaTexto: "Acometida aérea, subterránea o mixta", explicacion: "Según su trazado, la acometida puede ser aérea (mediante conductores tensados), subterránea (enterrada) o mixta (combinación de ambas)." },
  { id: 600620, tema: "U6: Configuración de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué finalidad tiene la instalación de un interruptor de corte omnipolar en el Cuadro General de Mando y Protección?", opciones: ["Permitir desconectar simultáneamente todas las fases y el neutro de la instalación", "Desconectar únicamente una fase de la instalación", "Aumentar la potencia contratada sin ningún trámite", "Sustituir la función del diferencial"], correctaTexto: "Permitir desconectar simultáneamente todas las fases y el neutro de la instalación", explicacion: "El interruptor de corte omnipolar permite desconectar simultáneamente todos los conductores activos (fases y, en su caso, neutro) de la instalación interior del usuario." }
];

const TEMA_DISTRIBUCION_U7_DATA = [
  { id: 600701, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Cuál es el procedimiento correcto para instalar una acometida aérea en una vivienda?", opciones: ["Simplemente clavar el cable sin protección", "Utilizar conductores aislados, cables portantes y protección mecánica en su paso por la fachada", "Usar cables de baja calidad para ahorrar dinero", "No es necesario proteger la acometida"], correctaTexto: "Utilizar conductores aislados, cables portantes y protección mecánica en su paso por la fachada", explicacion: "Las acometidas aéreas deben estar formadas por conductores aislados, incluir cable portante y contar con protección mecánica en puntos de paso." },
  { id: 600702, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Cuál es la profundidad mínima de enterramiento para una acometida subterránea?", opciones: ["10 centímetros", "20 centímetros", "60 centímetros", "1 metro"], correctaTexto: "60 centímetros", explicacion: "Las acometidas subterráneas deben estar enterradas a una profundidad mínima de 60 cm para protección contra daños mecánicos y cambios climáticos." },
  { id: 600703, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Cómo se realiza el montaje de los fusibles en una CPM?", opciones: ["Con los dedos sin protección", "Usando herramientas aislantes, con la instalación desenergizada y verificando la ausencia de tensión", "Mientras la instalación está en funcionamiento", "De cualquier forma rápidamente"], correctaTexto: "Usando herramientas aislantes, con la instalación desenergizada y verificando la ausencia de tensión", explicacion: "El montaje de fusibles requiere desenergizar la instalación, verificar la ausencia de tensión con probador y usar herramientas aisladas." },
  { id: 600704, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Cuál es la diferencia entre montar un TI (Toroid) en serie o en paralelo?", opciones: ["No hay diferencia", "En serie (correcto): pasa la corriente de acometida; En paralelo: NO debe hacerse, destruiría el TI", "En paralelo es más eficiente", "En serie rompe el circuito"], correctaTexto: "En serie (correcto): pasa la corriente de acometida; En paralelo: NO debe hacerse, destruiría el TI", explicacion: "El TI DEBE montarse en serie en la acometida. Nunca en paralelo, pues su resistencia baja haría un cortocircuito." },
  { id: 600705, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Cómo se sustituye un fusible fundido en una CPM?", opciones: ["Con un trozo de alambre", "Desenergizar la instalación, verificar ausencia de tensión, desmontar el fusible y colocar uno nuevo de la misma intensidad", "Sin desconectar nada", "Con el fusible de mayor intensidad que se encuentre"], correctaTexto: "Desenergizar la instalación, verificar ausencia de tensión, desmontar el fusible y colocar uno nuevo de la misma intensidad", explicacion: "La sustitución de fusibles se realiza con procedimiento de seguridad: desenergizar, verificar ausencia de tensión, y usar fusible de igual intensidad." },
  { id: 600706, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué comprobación previa se debe realizar antes de dar de alta un nuevo suministro en la centralización de contadores?", opciones: ["Verificar la correcta conexión de fases, neutro y conductor de protección, y la ausencia de cortocircuitos", "Conectar directamente sin ninguna comprobación", "Solo verificar el color de la carcasa del contador", "Encender la instalación sin desconectar antes la CGP"], correctaTexto: "Verificar la correcta conexión de fases, neutro y conductor de protección, y la ausencia de cortocircuitos", explicacion: "Antes de dar de alta un suministro se debe verificar la correcta conexión de todos los conductores y comprobar la ausencia de cortocircuitos o defectos de aislamiento." },
  { id: 600707, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué mantenimiento periódico se recomienda realizar sobre la Caja General de Protección (CGP)?", opciones: ["Revisión del estado de los fusibles, ausencia de humedad interior y correcto cierre de la envolvente", "Ningún mantenimiento es necesario", "Sustitución completa cada mes", "Solo limpieza exterior sin revisión interna"], correctaTexto: "Revisión del estado de los fusibles, ausencia de humedad interior y correcto cierre de la envolvente", explicacion: "El mantenimiento periódico de la CGP incluye revisar el estado de los fusibles, comprobar la ausencia de humedad en su interior y verificar que la envolvente cierra correctamente." },
  { id: 600708, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué procedimiento de seguridad debe seguirse al manipular la Línea General de Alimentación (LGA) de un edificio?", opciones: ["Coordinar la desconexión con la compañía distribuidora y verificar ausencia de tensión antes de manipular", "Manipular directamente sin coordinación previa con la distribuidora", "No es necesario verificar tensión si se trabaja rápido", "Usar herramientas sin aislar bajo ninguna circunstancia"], correctaTexto: "Coordinar la desconexión con la compañía distribuidora y verificar ausencia de tensión antes de manipular", explicacion: "Dado que la LGA puede estar bajo la responsabilidad de la compañía distribuidora en su origen, cualquier manipulación debe coordinarse con ella y verificar siempre la ausencia de tensión antes de actuar." },
  { id: 600709, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué se debe verificar al realizar el mantenimiento de las derivaciones individuales de un edificio?", opciones: ["El estado del aislamiento, ausencia de sobrecalentamiento y correcto etiquetado de cada derivación", "Solo el color del cable sin más comprobaciones", "No requieren ningún tipo de mantenimiento", "Sustituir todas las derivaciones cada año sin comprobación previa"], correctaTexto: "El estado del aislamiento, ausencia de sobrecalentamiento y correcto etiquetado de cada derivación", explicacion: "El mantenimiento de las derivaciones individuales incluye comprobar el estado del aislamiento, detectar posibles sobrecalentamientos y verificar que cada derivación esté correctamente etiquetada e identificada." },
  { id: 600710, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué acción se debe realizar si se detecta corrosión o humedad en el interior de una Caja General de Protección?", opciones: ["Limpiar, secar y reparar la estanqueidad de la envolvente, sustituyendo elementos deteriorados", "Ignorar el problema si la instalación sigue funcionando", "Sellar la caja sin realizar ninguna reparación interna", "Aumentar la potencia contratada para compensar el problema"], correctaTexto: "Limpiar, secar y reparar la estanqueidad de la envolvente, sustituyendo elementos deteriorados", explicacion: "Ante corrosión o humedad debe procederse a limpiar y secar el interior, reparar la estanqueidad de la envolvente y sustituir los elementos deteriorados para evitar fallos futuros." },
  { id: 600711, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué protección mecánica adicional se recomienda para una acometida aérea que cruza una calle o zona de tránsito de vehículos?", opciones: ["Instalar la acometida a una altura mínima de seguridad establecida por normativa", "No es necesario adoptar ninguna medida especial", "Colocar la acometida a ras de suelo", "Utilizar cable desnudo sin protección mecánica"], correctaTexto: "Instalar la acometida a una altura mínima de seguridad establecida por normativa", explicacion: "Las acometidas aéreas que cruzan calles o zonas de tránsito deben instalarse respetando la altura mínima de seguridad establecida por la normativa para evitar riesgos de contacto con vehículos." },
  { id: 600712, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué elemento debe verificarse al sustituir un contador de energía en la centralización de contadores?", opciones: ["El precintado correcto del nuevo contador y la correcta reconexión de fases, neutro y comunicaciones", "Solo el precio del contador nuevo", "No es necesario precintar el nuevo contador", "Basta con conectar cualquier cable sin verificar el orden de fases"], correctaTexto: "El precintado correcto del nuevo contador y la correcta reconexión de fases, neutro y comunicaciones", explicacion: "Al sustituir un contador debe verificarse el correcto precintado (obligatorio por normativa para evitar manipulaciones) y la correcta reconexión de todos los conductores, incluidas las comunicaciones si las hubiera." },
  { id: 600713, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué medida se debe adoptar si se detecta una acometida subterránea dañada por obras cercanas?", opciones: ["Señalizar la zona, desenergizar si es posible y notificar de inmediato a la compañía distribuidora", "Continuar la obra sin notificar a nadie", "Reparar el cable sin desconectar la tensión", "Ignorar el daño si el cable sigue funcionando aparentemente"], correctaTexto: "Señalizar la zona, desenergizar si es posible y notificar de inmediato a la compañía distribuidora", explicacion: "Ante una acometida subterránea dañada debe señalizarse la zona, evitar el contacto, desenergizar si es posible y notificar de inmediato a la compañía distribuidora para su reparación segura." },
  { id: 600714, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué comprobación de seguridad es imprescindible antes de abrir una Caja General de Protección para su mantenimiento?", opciones: ["Verificar la ausencia de tensión en su interior mediante un detector homologado, dado que puede permanecer en tensión aunque el usuario esté desconectado", "Abrir directamente sin verificación, ya que nunca tiene tensión", "Solo comprobar que el contador marca cero consumo", "No es necesario ningún tipo de comprobación previa"], correctaTexto: "Verificar la ausencia de tensión en su interior mediante un detector homologado, dado que puede permanecer en tensión aunque el usuario esté desconectado", explicacion: "La CGP puede permanecer en tensión aunque la instalación interior del usuario esté desconectada, ya que recibe la alimentación directamente de la red de distribución, por lo que siempre debe verificarse la ausencia de tensión antes de manipularla." },
  { id: 600715, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué es el 'punto de conexión y medida' en el contexto de una nueva instalación de enlace?", opciones: ["El punto donde la compañía distribuidora conecta la acometida y donde se ubica la medida del suministro", "Un punto exclusivo para conexión de fibra óptica", "El punto final de la instalación interior de la vivienda", "Un elemento decorativo sin función técnica"], correctaTexto: "El punto donde la compañía distribuidora conecta la acometida y donde se ubica la medida del suministro", explicacion: "El punto de conexión y medida es el lugar donde la compañía distribuidora conecta la acometida a la red pública y donde se instalan los equipos de medida del consumo del usuario." },
  { id: 600716, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué herramienta se debe emplear para el pelado y preparación de los extremos de un cable de acometida antes de su conexión?", opciones: ["Pelacables o cuchilla específica que no dañe el conductor interior", "Un simple cutter sin ningún cuidado especial", "Los dientes, en ausencia de herramienta adecuada", "Cualquier herramienta metálica disponible sin importar el filo"], correctaTexto: "Pelacables o cuchilla específica que no dañe el conductor interior", explicacion: "Debe emplearse un pelacables o cuchilla específica que retire el aislamiento sin dañar los hilos del conductor, garantizando una conexión segura." },
  { id: 600717, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué medida se debe tomar respecto al par de apriete de los bornes de conexión en una CGP o centralización de contadores?", opciones: ["Respetar el par de apriete indicado por el fabricante para evitar falsos contactos", "Apretar al máximo posible sin ningún límite", "No es relevante el par de apriete aplicado", "Dejar los bornes sueltos para facilitar futuras intervenciones"], correctaTexto: "Respetar el par de apriete indicado por el fabricante para evitar falsos contactos", explicacion: "Un apriete insuficiente o excesivo de los bornes puede provocar falsos contactos, calentamientos o daños en los terminales, por lo que debe respetarse el par de apriete indicado por el fabricante." },
  { id: 600718, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué se debe comprobar tras realizar el mantenimiento de una instalación de enlace antes de dejarla en servicio?", opciones: ["El correcto cierre de armarios y envolventes, y ausencia de elementos sueltos u olvidados", "No es necesario comprobar nada tras el mantenimiento", "Solo verificar el aspecto estético exterior", "Dejar los armarios abiertos para facilitar la próxima revisión"], correctaTexto: "El correcto cierre de armarios y envolventes, y ausencia de elementos sueltos u olvidados", explicacion: "Tras cualquier intervención de mantenimiento debe verificarse el correcto cierre de armarios y envolventes, así como la ausencia de herramientas o elementos olvidados en el interior." },
  { id: 600719, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué normativa regula el etiquetado e identificación de los distintos circuitos y derivaciones en una instalación de enlace?", opciones: ["El REBT y sus ITC correspondientes, que exigen una identificación clara de cada elemento", "No existe ninguna exigencia normativa de etiquetado", "Solo se etiquetan las instalaciones industriales, nunca las residenciales", "El etiquetado es opcional y queda a criterio del instalador"], correctaTexto: "El REBT y sus ITC correspondientes, que exigen una identificación clara de cada elemento", explicacion: "El REBT exige la correcta identificación y etiquetado de los distintos circuitos, protecciones y derivaciones para facilitar su mantenimiento y evitar errores de manipulación." },
  { id: 600720, tema: "U7: Montaje y mantenimiento de instalaciones de enlace (TEST OFICIAL)", texto: "¿Qué actuación se debe realizar si, al verificar una derivación individual, se detecta una sección de conductor insuficiente para la potencia contratada?", opciones: ["Sustituir el conductor por uno de sección adecuada según los cálculos de intensidad y caída de tensión", "Aumentar la potencia del interruptor automático sin cambiar el conductor", "Ignorar el problema si no se ha producido ningún incidente todavía", "Reducir la potencia contratada sin verificar la instalación"], correctaTexto: "Sustituir el conductor por uno de sección adecuada según los cálculos de intensidad y caída de tensión", explicacion: "Ante una sección insuficiente debe sustituirse el conductor por uno adecuado a la intensidad prevista y a la caída de tensión máxima permitida, nunca aumentar la protección sin adecuar el cableado." }
];

